const resposta = $json;

// A API retornou como array
const objetoData = Array.isArray(resposta) ? resposta[0] : resposta;

const dataKey = Object.keys(objetoData || {})[0];
const lista = objetoData[dataKey] || [];

// Filtra só horários disponíveis
const horariosDisponiveis = lista
  .filter(item => item.status === "Y")
  .map(item => item.time);

// Montar mensagem amigável
let mensagem;

if (horariosDisponiveis.length === 0) {
  mensagem = "No momento não há horários disponíveis para essa data. Gostaria de verificar outra data?";
} else {
  mensagem = `Esses são horários disponíveis para essa data: ${horariosDisponiveis.join(", ")}.`;
}

return [{
  status: "sucesso",
  acao: "horarios",
  data: dataKey,
  horarios_disponiveis: horariosDisponiveis,
  mensagem
}];

