// Pega todos os itens vindos do GET /convenios
const items = $input.all();

// Se veio como vários itens separados
let lista = items.map(i => i.json);

// Se veio como 1 item contendo array
if (lista.length === 1 && Array.isArray(lista[0])) {
  lista = lista[0];
}

// Pega o convênio informado no node Validar campos
const nomeInputRaw = $('Validar campos (agendar)').first().json.paciente?.convenio || "";

const nomeInput = nomeInputRaw
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .trim();

if (!nomeInput) {
  return [{
    status: "erro",
    mensagem: "Convênio não informado."
  }];
}

// Agora sim é seguro usar find
const encontrado = lista.find(c => {
  const nomeApi = (c.convenio_nome || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();

  return nomeApi === nomeInput;
});

if (!encontrado) {
  return [{
    status: "erro",
    mensagem: `Convênio "${nomeInputRaw}" não encontrado na clínica.`
  }];
}

return [{
  status: "ok",
  id_convenio: encontrado.id_convenio,
  convenio_nome_oficial: encontrado.convenio_nome
}];

function normalizar(texto) {
  return String(texto || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function somenteDigitos(valor) {
  return String(valor || "").replace(/\D/g, "");
}

function formatarCPF(cpf) {
  const d = somenteDigitos(cpf);
  if (d.length !== 11) return cpf;
  return `${d.slice(0,3)}.${d.slice(3,6)}.${d.slice(6,9)}-${d.slice(9)}`;
}

function converterData(dataInput) {
  if (!dataInput) return { iso: null, br: null };

  const data = String(dataInput).trim();

  // Já está ISO YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    const [ano, mes, dia] = data.split("-");
    return {
      iso: data,
      br: `${dia}/${mes}/${ano}`
    };
  }

  // Está DD/MM/YYYY
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(data)) {
    const [dia, mes, ano] = data.split("/");
    return {
      iso: `${ano}-${mes}-${dia}`,
      br: data
    };
  }

  return { iso: null, br: null };
}

const input = $json.body || $json;

// ============================
// MAPEAR MÉDICO
// ============================

const medicoInput = input.medico;
const medicoNormalizado = normalizar(medicoInput);

const mapa = [
  {
    palavras: ["yugo", "yamazaki"],
    cpf: "000.000.000-00",
    nome_oficial: "Dr. Yugo Yamazaki"
  },
  {
    palavras: ["rubens", "martins"],
    cpf: "000.000.000-00",
    nome_oficial: "Dr. Rubens Martins Filho"
  },
  {
    palavras: ["engler", "mori"],
    cpf: "000.000.000-00",
    nome_oficial: "Dr. Engler Mori Ferreira"
  },
  {
    palavras: ["luiz", "henrique", "cunha"],
    cpf: "000.000.000-00",
    nome_oficial: "Dr. Luiz H. Cunha"
  }
];

let encontrado = mapa.find(item =>
  item.palavras.some(p => medicoNormalizado.includes(p))
);

let cpf_profissional = null;
let medico_nome_oficial = null;

if (encontrado) {
  cpf_profissional = encontrado.cpf;
  medico_nome_oficial = encontrado.nome_oficial;
}

// ============================
// PADRONIZAR DATA
// ============================

const dataConvertida = converterData(input.data);

// ============================
// RETORNO FINAL PADRONIZADO
// ============================

return [{
  ...input,
  cpf_profissional,
  medico_nome_oficial,
  cpf: formatarCPF(input.cpf),
  data_iso: dataConvertida.iso, // YYYY-MM-DD
  data_br: dataConvertida.br    // DD/MM/YYYY
}];

function normalizar(texto) {
  return String(texto || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function somenteDigitos(valor) {
  return String(valor || "").replace(/\D/g, "");
}

function formatarCPF(cpf) {
  const d = somenteDigitos(cpf);
  if (d.length !== 11) return null;
  return `${d.slice(0,3)}.${d.slice(3,6)}.${d.slice(6,9)}-${d.slice(9)}`;
}

function converterData(dataInput) {
  if (!dataInput) return { iso: null, br: null };

  const data = String(dataInput).trim();

  if (/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    const [ano, mes, dia] = data.split("-");
    return { iso: data, br: `${dia}/${mes}/${ano}` };
  }

  if (/^\d{2}\/\d{2}\/\d{4}$/.test(data)) {
    const [dia, mes, ano] = data.split("/");
    return { iso: `${ano}-${mes}-${dia}`, br: data };
  }

  return { iso: null, br: null };
}

function converterDataBR(dataInput) {
  if (!dataInput) return null;

  const data = String(dataInput).trim();

  if (/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    const [ano, mes, dia] = data.split("-");
    return `${dia}/${mes}/${ano}`;
  }

  if (/^\d{2}\/\d{2}\/\d{4}$/.test(data)) {
    return data;
  }

  return null;
}

function normalizarHora(horaInput) {
  if (!horaInput) return null;

  let hora = String(horaInput).toLowerCase().trim();
  hora = hora.replace(/\s/g, "");

  if (/^\d{1,2}h$/.test(hora)) {
    hora = hora.replace("h", ":00");
  }

  if (/^\d{1,2}$/.test(hora)) {
    hora = hora + ":00";
  }

  if (/^\d{1,2}:\d{1}$/.test(hora)) {
    const [h, m] = hora.split(":");
    hora = `${h}:${m.padStart(2, "0")}`;
  }

  if (/^\d{1,2}:\d{2}$/.test(hora)) {
    const [h, m] = hora.split(":").map(Number);
    if (h >= 0 && h <= 23 && m >= 0 && m <= 59) {
      return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}`;
    }
  }

  return null;
}

function normalizarGenero(generoInput) {
  if (!generoInput) return null;
  const g = normalizar(generoInput);
  if (g.startsWith("f")) return "F";
  if (g.startsWith("m")) return "M";
  return null;
}

// ===== NOVA LÓGICA DE CONVÊNIO =====

function tratarConvenio(convenioInput, numeroCarteirinha) {
  const conv = normalizar(convenioInput);

  const conveniosPermitidos = [
    "unimed",
    "ipsemg",
    "sul america",
    "particular",
    "bom pastor",
    "sao luiz",
    "tabela social"
  ];

  const encontrado = conveniosPermitidos.find(c =>
    conv.includes(c)
  );

  if (!encontrado) {
    return { erro: "Convênio não aceito pela clínica." };
  }

  // Carteirinha obrigatória
  if (
    ["unimed", "ipsemg", "sul america"].includes(encontrado) &&
    !numeroCarteirinha
  ) {
    return { erro: "Número da carteirinha é obrigatório para esse convênio." };
  }

  // Definir valor
  let valor = 450; // padrão particular

  if (encontrado !== "particular") {
    valor = 300;
  }

  return {
    nome_normalizado: encontrado,
    valor_consulta: valor
  };
}

// ===========================
// INÍCIO
// ===========================

const input = $json.body || $json;

const medicoNormalizado = normalizar(input.medico);

const mapa = [
  { palavras: ["yugo"], cpf: "000.000.000-00", nome: "Dr. Yugo Yamazaki" },
  { palavras: ["rubens"], cpf: "000.000.000-00", nome: "Dr. Rubens Martins Filho" },
  { palavras: ["engler"], cpf: "000.000.000-00", nome: "Dr. Engler Mori Ferreira" },
  { palavras: ["luiz"], cpf: "000.000.000-00", nome: "Dr. Luiz H. Cunha" }
];

const encontrado = mapa.find(m =>
  m.palavras.some(p => medicoNormalizado.includes(p))
);

const dataConvertida = converterData(input.data);

const pacienteCPF = somenteDigitos(input.paciente?.cpf);
const pacienteCPFFormatado = formatarCPF(pacienteCPF);

const convenioTratado = tratarConvenio(
  input.paciente?.convenio,
  input.paciente?.numero_carteirinha
);

if (convenioTratado.erro) {
  return [{
    status: "erro",
    mensagem: convenioTratado.erro
  }];
}

// ===========================
// RETORNO FINAL
// ===========================

return [{
  ...input,

  status: "ok",

  cpf_profissional: encontrado?.cpf || null,
  medico_nome_oficial: encontrado?.nome || null,

  data_iso: dataConvertida.iso,
  data_br: dataConvertida.br,

  hora: normalizarHora(input.hora),

  valor_consulta: convenioTratado.valor_consulta,
  convenio_normalizado: convenioTratado.nome_normalizado,

  paciente: {
    ...input.paciente,
    cpf: pacienteCPF,
    cpf_formatado: pacienteCPFFormatado,
    telefone: somenteDigitos(input.paciente?.telefone),
    genero: normalizarGenero(input.paciente?.genero),
    data_nascimento: converterDataBR(input.paciente?.data_nascimento)
  }
}];

